/* AI Notebook — Workspace Redesign Override
   Ports the AINotebook1 visual design system onto the original app's existing class names.
   Loaded after all original stylesheets to override tokens and component styles.
   All original JS/DOM contracts remain intact. */

@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@500;600;700&display=swap');

/* ============ ROOT TOKENS ============ */
:root {
  --accent: #f36d9d;
  --accent-soft: rgba(243,109,157,.12);
  --accent-strong: #ff93b7;
  --rd-bg: #101116;
  --rd-panel: #171920;
  --rd-sidebar: #14161c;
  --rd-border: #2a2e39;
  --rd-border-light: #303440;
  --rd-text: #f3f5fa;
  --rd-text-muted: #848b9a;
  --rd-text-dim: #656b7a;
  --rd-font: 'DM Sans', sans-serif;
  --rd-display: 'Space Grotesk', sans-serif;
}

/* Accent variants */
[data-accent="rose"], .accent-rose { --accent: #f36d9d; --accent-soft: rgba(243,109,157,.12); --accent-strong: #ff93b7; }
[data-accent="blue"], .accent-blue { --accent: #67a7ff; --accent-soft: rgba(103,167,255,.12); --accent-strong: #93c3ff; }
[data-accent="amber"], .accent-amber { --accent: #e8ad67; --accent-soft: rgba(232,173,103,.12); --accent-strong: #f3c88f; }
[data-accent="green"], .accent-green { --accent: #5fc4a5; --accent-soft: rgba(95,196,165,.12); --accent-strong: #8ce0c4; }
[data-accent="violet"] { --accent: #a78bfa; --accent-soft: rgba(167,139,250,.12); --accent-strong: #c4b5fd; }

/* ============ BASE ============ */
body, .app-shell {
  font-family: var(--rd-font) !important;
  background: var(--rd-bg) !important;
  color: var(--rd-text) !important;
}

h1, h2, h3, .brand-text, .landing-brand, .cl-brand, .cl-mini-heading,
.note-title-input, .mini-heading, .system-copy h3, .feature-copy h2,
.demo-note-editor h3, .summary-result h3, .editor-toolbar strong,
.panel-heading strong, .section-heading h2, .set-card h3 {
  font-family: var(--rd-display) !important;
  letter-spacing: -.045em !important;
}

/* Focus ring */
button:focus-visible, input:focus-visible, textarea:focus-visible, select:focus-visible {
  outline: 2px solid var(--accent) !important;
  outline-offset: 3px !important;
}

/* ============ APP SHELL ============ */
.app-shell {
  display: flex !important;
  min-height: 100vh !important;
  background: var(--rd-bg) !important;
}

/* ============ SIDEBAR ============ */
.sidebar {
  width: 256px !important;
  flex: 0 0 256px !important;
  border-right: 1px solid #242731 !important;
  background: var(--rd-sidebar) !important;
  display: flex !important;
  flex-direction: column !important;
  padding: 22px 14px 16px !important;
  transition: width .25s ease, flex-basis .25s ease !important;
  position: relative !important;
  z-index: 20 !important;
}

.sidebar.collapsed {
  width: 76px !important;
  flex-basis: 76px !important;
}

.sidebar .side-head,
.sidebar .brand-row {
  display: flex !important;
  align-items: center !important;
  gap: 10px !important;
  height: 34px !important;
  margin-bottom: 28px !important;
  padding: 0 6px !important;
}

.sidebar .brand,
.sidebar .side-head .brand {
  display: flex !important;
  align-items: center !important;
  gap: 10px !important;
  text-decoration: none !important;
}

.sidebar .logo, .sidebar .brand .logo {
  width: 31px !important;
  height: 31px !important;
  border-radius: 9px !important;
  overflow: hidden !important;
  background: #fff !important;
  flex: none !important;
  display: grid !important;
  place-items: center !important;
}

.sidebar .logo img, .sidebar .brand .logo img {
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
}

.sidebar .brand-text, .sidebar .brand span:not(.logo) {
  font-family: var(--rd-display) !important;
  font-size: 18px !important;
  font-weight: 700 !important;
  letter-spacing: -.04em !important;
  color: #f7f8fb !important;
}

.sidebar .brand-text .grad-text,
.sidebar .brand .grad-text {
  color: #8d93a2 !important;
  font-weight: 500 !important;
}

.sidebar .collapse-btn, .sidebar-toggle {
  border: 1px solid transparent !important;
  background: transparent !important;
  color: #9298a8 !important;
  border-radius: 8px !important;
  height: 32px !important;
  width: 32px !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  cursor: pointer !important;
  transition: all .18s ease !important;
}

.sidebar .collapse-btn:hover, .sidebar-toggle:hover {
  background: #232631 !important;
  color: #f0f2f7 !important;
  border-color: #303441 !important;
}

/* Sidebar nav */
.sidebar .side-nav, .sidebar nav.main-nav {
  display: flex !important;
  flex-direction: column !important;
  gap: 3px !important;
  flex: 1 !important;
  overflow-y: auto !important;
}

.sidebar .nav-section, .sidebar .nav-label {
  color: var(--rd-text-dim) !important;
  text-transform: uppercase !important;
  letter-spacing: .12em !important;
  font-size: 10px !important;
  font-weight: 700 !important;
  padding: 0 11px !important;
  margin: 0 0 10px !important;
}

.sidebar .nav-section + .nav-section,
.sidebar .nav-label.secondary-label {
  margin-top: 30px !important;
}

.sidebar .nav-item, .sidebar .side-nav a, .sidebar .side-nav button {
  display: flex !important;
  align-items: center !important;
  gap: 12px !important;
  width: 100% !important;
  border: 1px solid transparent !important;
  background: transparent !important;
  color: #8e95a5 !important;
  padding: 10px 11px !important;
  border-radius: 9px !important;
  text-align: left !important;
  font-size: 13px !important;
  position: relative !important;
  transition: .18s ease !important;
  text-decoration: none !important;
}

.sidebar .nav-item:hover, .sidebar .side-nav a:hover, .sidebar .side-nav button:hover {
  color: #e3e6ed !important;
  background: #1e212a !important;
}

.sidebar .nav-item.active, .sidebar .side-nav a.active, .sidebar .side-nav button.active {
  color: #f4f6fb !important;
  background: var(--accent-soft) !important;
  border-color: color-mix(in srgb, var(--accent) 22%, transparent) !important;
}

.sidebar .nav-item.active i, .sidebar .side-nav a.active i {
  color: var(--accent-strong) !important;
}

.sidebar .nav-primary {
  background: var(--accent-soft) !important;
  border: 1px solid color-mix(in srgb, var(--accent) 22%, transparent) !important;
  color: #f4f6fb !important;
}

.sidebar.collapsed .nav-item,
.sidebar.collapsed .side-nav a,
.sidebar.collapsed .side-nav button {
  justify-content: center !important;
  padding: 10px 0 !important;
}

.sidebar.collapsed .nav-item span,
.sidebar.collapsed .nav-label,
.sidebar.collapsed .brand-text,
.sidebar.collapsed .side-foot,
.sidebar.collapsed .workspace-switcher span:not(.workspace-avatar) {
  display: none !important;
}

/* Sidebar footer */
.sidebar .side-foot, .sidebar .sidebar-bottom {
  margin-top: auto !important;
  padding-top: 16px !important;
}

.sidebar .side-user-card {
  display: flex !important;
  align-items: center !important;
  gap: 10px !important;
  padding: 9px !important;
  border: 1px solid #292d38 !important;
  background: #1b1e26 !important;
  border-radius: 10px !important;
  color: #8f95a5 !important;
}

.sidebar .side-user-name {
  color: #e8eaf0 !important;
  font-size: 12px !important;
  font-weight: 600 !important;
}

.sidebar .side-user-trigger {
  border: 0 !important;
  background: none !important;
  cursor: pointer !important;
  width: 100% !important;
}

/* ============ MAIN CONTENT ============ */
.content, .main-content {
  flex: 1 !important;
  min-width: 0 !important;
  background: var(--rd-bg) !important;
}

/* ============ TOPBAR ============ */
.topbar {
  height: 74px !important;
  padding: 0 42px !important;
  border-bottom: 1px solid #242731 !important;
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  background: rgba(16,17,22,.8) !important;
  flex-wrap: nowrap !important;
}

.topbar > div:first-child {
  display: flex !important;
  flex-direction: column !important;
  gap: 2px !important;
}

.topbar .eyebrow {
  color: var(--rd-text-dim) !important;
  text-transform: uppercase !important;
  letter-spacing: .12em !important;
  font-size: 10px !important;
  font-weight: 700 !important;
  margin: 0 !important;
}

.topbar h1 {
  font-family: var(--rd-display) !important;
  font-size: clamp(20px, 2.5vw, 28px) !important;
  letter-spacing: -.04em !important;
  color: #f2f4f8 !important;
  margin: 0 !important;
}

.topbar .sub {
  color: var(--rd-text-muted) !important;
  font-size: 13px !important;
  margin: 2px 0 0 !important;
}

.topbar-actions {
  display: flex !important;
  align-items: center !important;
  gap: 11px !important;
}

/* Search trigger */
.search-trigger {
  display: flex !important;
  align-items: center !important;
  gap: 8px !important;
  border: 1px solid #292d38 !important;
  background: #171920 !important;
  color: #7f8696 !important;
  border-radius: 8px !important;
  font-size: 11px !important;
  padding: 7px 9px !important;
  cursor: pointer !important;
}

.search-trigger .kbd, .search-trigger kbd {
  color: #666d7e !important;
  border: 1px solid #313540 !important;
  padding: 2px 5px !important;
  border-radius: 4px !important;
  font-size: 9px !important;
  margin-left: 15px !important;
}

/* ============ BUTTONS ============ */
.btn {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 7px !important;
  border-radius: 8px !important;
  font-size: 12px !important;
  font-weight: 600 !important;
  padding: 9px 13px !important;
  transition: .18s ease !important;
  font-family: var(--rd-font) !important;
  cursor: pointer !important;
  text-decoration: none !important;
}

.btn.primary, .btn.block {
  background: var(--accent) !important;
  border: 1px solid var(--accent) !important;
  color: #17151a !important;
  box-shadow: 0 5px 18px color-mix(in srgb, var(--accent) 20%, transparent) !important;
}

.btn.primary:hover, .btn.block:hover {
  background: var(--accent-strong) !important;
  transform: translateY(-1px) !important;
}

.btn.ghost, .btn.secondary, .btn.outline, .btn.subtle {
  background: #1b1e26 !important;
  border: 1px solid #303440 !important;
  color: #ced2dc !important;
}

.btn.ghost:hover, .btn.secondary:hover, .btn.outline:hover, .btn.subtle:hover {
  background: #252934 !important;
  border-color: #454b5a !important;
}

.btn.danger {
  background: transparent !important;
  border: 1px solid #5e3542 !important;
  color: #db8ca6 !important;
}

.btn.danger:hover {
  background: rgba(176,72,104,.12) !important;
}

.btn.small {
  padding: 7px 11px !important;
  font-size: 11px !important;
}

/* ============ PANELS / CARDS ============ */
.panel, .glass, .dash-section, .tool-card,
.set-card, .recent-panel, .focus-panel,
.chat-history, .conversation, .notes-list,
.note-editor, .summary-input, .summary-output,
.mindmap-canvas, .roadmap-empty, .settings-nav {
  border: 1px solid var(--rd-border) !important;
  border-radius: 12px !important;
  background: var(--rd-panel) !important;
  backdrop-filter: none !important;
}

.panel.glass, .glass {
  background: var(--rd-panel) !important;
  box-shadow: none !important;
}

/* ============ DASHBOARD ============ */
.learn-launcher, .learn-launcher.glass {
  border: 1px solid var(--rd-border) !important;
  border-radius: 14px !important;
  background: linear-gradient(115deg, #1d202a 0%, #181a22 55%, #191c29 100%) !important;
  padding: 37px 42px !important;
  position: relative !important;
  overflow: hidden !important;
}

.learn-launcher .ll-copy h2 {
  font-family: var(--rd-display) !important;
  font-size: clamp(22px, 3vw, 30px) !important;
  color: #f4f5f8 !important;
}

.learn-launcher .ll-form {
  display: flex !important;
  align-items: center !important;
  gap: 10px !important;
  margin-top: 18px !important;
}

.learn-launcher .ll-form input {
  flex: 1 !important;
  border: 1px solid #303440 !important;
  background: #1c1f27 !important;
  color: #cfd3dd !important;
  border-radius: 8px !important;
  padding: 11px 14px !important;
  font-size: 13px !important;
  font-family: var(--rd-font) !important;
}

.learn-launcher .ll-form input:focus {
  border-color: color-mix(in srgb, var(--accent) 58%, #303440) !important;
  outline: none !important;
}

/* Stats grid */
.stats-grid {
  display: grid !important;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)) !important;
  gap: 12px !important;
}

.stat-card, .stat-card.glass {
  border: 1px solid var(--rd-border) !important;
  border-radius: 12px !important;
  background: var(--rd-panel) !important;
  padding: 17px !important;
}

.stat-card .ic {
  width: 34px !important;
  height: 34px !important;
  border-radius: 9px !important;
  display: grid !important;
  place-items: center !important;
  margin-bottom: 12px !important;
}

.stat-card b {
  font-family: var(--rd-display) !important;
  font-size: 28px !important;
  color: #f2f4f8 !important;
  display: block !important;
}

.stat-card span {
  color: var(--rd-text-muted) !important;
  font-size: 11px !important;
}

/* Workspace grid */
.workspace-grid {
  display: grid !important;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)) !important;
  gap: 12px !important;
}

.ws-card, .workspace-grid .ws-card {
  border: 1px solid #2b2f3a !important;
  border-radius: 11px !important;
  background: #181a21 !important;
  padding: 17px !important;
  text-decoration: none !important;
  color: #8a91a1 !important;
  transition: .18s ease !important;
  position: relative !important;
  min-height: 120px !important;
  display: flex !important;
  flex-direction: column !important;
  gap: 8px !important;
}

.ws-card:hover {
  border-color: #454b5a !important;
  transform: translateY(-2px) !important;
  background: #1c1f27 !important;
}

.ws-card .ws-ic, .ws-card i {
  width: 34px !important;
  height: 34px !important;
  border-radius: 9px !important;
  display: grid !important;
  place-items: center !important;
  background: rgba(128,151,239,.13) !important;
  color: #8dafef !important;
  font-size: 16px !important;
}

.ws-card strong, .ws-card b {
  color: #e4e6ec !important;
  font-size: 13px !important;
}

.ws-card span, .ws-card small {
  color: #8a91a1 !important;
  font-size: 11px !important;
}

/* Topics grid */
.topics-grid {
  display: grid !important;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)) !important;
  gap: 12px !important;
}

.topic-card {
  border: 1px solid var(--rd-border) !important;
  border-radius: 11px !important;
  background: var(--rd-panel) !important;
  padding: 16px !important;
  text-decoration: none !important;
  color: #cfd3dd !important;
  transition: .18s ease !important;
}

.topic-card:hover {
  border-color: #454b5a !important;
  transform: translateY(-2px) !important;
}

/* Trending grid */
.trending-grid {
  display: grid !important;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)) !important;
  gap: 10px !important;
}

.trend-card {
  border: 1px solid var(--rd-border) !important;
  border-radius: 10px !important;
  background: var(--rd-panel) !important;
  padding: 14px !important;
  text-decoration: none !important;
  color: #cfd3dd !important;
  cursor: pointer !important;
  transition: .18s ease !important;
}

.trend-card:hover {
  border-color: #454b5a !important;
}

/* Dash grids */
.dash-grid, .dash-grid-2 {
  display: grid !important;
  grid-template-columns: 1.4fr .8fr !important;
  gap: 12px !important;
  margin-bottom: 12px !important;
}

.dash-grid-2 {
  grid-template-columns: 1fr 1fr !important;
}

/* Panel heads */
.panel-head, .panel-heading {
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  margin-bottom: 16px !important;
}

.panel-head h3, .panel-heading h2, .panel-heading strong {
  font-family: var(--rd-display) !important;
  font-size: 15px !important;
  color: #dfe2e9 !important;
  margin: 0 !important;
}

/* Recent items */
.recent-list, .recent-item {
  display: flex !important;
  flex-direction: column !important;
  gap: 0 !important;
}

.recent-item {
  display: flex !important;
  flex-direction: row !important;
  gap: 11px !important;
  align-items: center !important;
  border-top: 1px solid #252934 !important;
  padding: 13px 0 !important;
  text-decoration: none !important;
  color: inherit !important;
}

.recent-item strong {
  color: #cfd3dd !important;
  font-size: 12px !important;
  display: block !important;
  margin-bottom: 4px !important;
}

.recent-item span, .recent-item small {
  color: #737a89 !important;
  font-size: 10px !important;
}

/* Progress ring */
.progress-ring {
  border: 1px solid var(--rd-border) !important;
  border-radius: 50% !important;
}

/* AI usage */
.ai-usage-bar .progress {
  border-radius: 6px !important;
  background: #252934 !important;
  overflow: hidden !important;
}

.ai-usage-bar .progress span {
  background: var(--accent) !important;
}

/* Model badges */
.model-badge, .model-selector {
  display: flex !important;
  align-items: center !important;
  gap: 7px !important;
  font-size: 11px !important;
  color: #8f95a5 !important;
}

.model-dot {
  width: 6px !important;
  height: 6px !important;
  border-radius: 50% !important;
  background: var(--accent) !important;
  display: inline-block !important;
}

.model-dot.off {
  background: #4a4d57 !important;
}

/* ============ CHAT ============ */
.chat-layout {
  display: grid !important;
  grid-template-columns: 245px 1fr !important;
  gap: 12px !important;
  min-height: 580px !important;
}

.chat-side {
  border: 1px solid var(--rd-border) !important;
  border-radius: 12px !important;
  background: var(--rd-panel) !important;
  padding: 15px !important;
  display: flex !important;
  flex-direction: column !important;
}

.chat-side-head .brand {
  display: flex !important;
  align-items: center !important;
  gap: 8px !important;
  margin-bottom: 16px !important;
}

.chat-side-head .logo {
  width: 28px !important;
  height: 28px !important;
  border-radius: 8px !important;
  overflow: hidden !important;
  background: #fff !important;
}

.chat-list {
  flex: 1 !important;
  overflow-y: auto !important;
  display: flex !important;
  flex-direction: column !important;
  gap: 4px !important;
}

.chat-list .chat-item, .chat-list > a, .chat-list > button {
  display: flex !important;
  align-items: center !important;
  gap: 8px !important;
  width: 100% !important;
  border: 1px solid transparent !important;
  background: transparent !important;
  color: #8e95a5 !important;
  padding: 10px 9px !important;
  border-radius: 8px !important;
  font-size: 11px !important;
  text-align: left !important;
  text-decoration: none !important;
  cursor: pointer !important;
  transition: .18s ease !important;
}

.chat-list .chat-item:hover, .chat-list > a:hover {
  background: #1e212a !important;
  color: #e3e6ed !important;
}

.chat-list .chat-item.active, .chat-list > a.active {
  background: var(--accent-soft) !important;
  border-color: color-mix(in srgb, var(--accent) 22%, transparent) !important;
  color: #d9dce5 !important;
}

/* Chat main */
.chat-main {
  border: 1px solid var(--rd-border) !important;
  border-radius: 12px !important;
  background: var(--rd-panel) !important;
  display: flex !important;
  flex-direction: column !important;
  overflow: hidden !important;
}

.chat-top, .conversation-header {
  border-bottom: 1px solid #2a2e39 !important;
  padding: 15px 18px !important;
  display: flex !important;
  justify-content: space-between !important;
  align-items: center !important;
}

.chat-top h1, .chat-top .chat-title {
  font-family: var(--rd-display) !important;
  font-size: 16px !important;
  color: #d9dce5 !important;
  margin: 0 !important;
}

.chat-top .eyebrow {
  color: var(--rd-text-dim) !important;
  font-size: 10px !important;
  text-transform: uppercase !important;
  letter-spacing: .12em !important;
}

/* Messages */
.messages {
  padding: 29px !important;
  flex: 1 !important;
  overflow: auto !important;
}

.msg, .message-row {
  display: flex !important;
  align-items: flex-start !important;
  gap: 11px !important;
  max-width: 700px !important;
  margin-bottom: 27px !important;
}

.msg.user, .message-row.user {
  margin-left: auto !important;
  flex-direction: row-reverse !important;
}

.msg .avatar, .message-avatar {
  flex: none !important;
  width: 28px !important;
  height: 28px !important;
  border-radius: 50% !important;
  display: grid !important;
  place-items: center !important;
  font-size: 9px !important;
  font-weight: 700 !important;
  background: #303440 !important;
  color: #e7eaf1 !important;
}

.msg.assistant .avatar, .message-row.assistant .avatar,
.message-row.assistant .message-avatar {
  background: #fff !important;
  overflow: hidden !important;
}

.msg .avatar img, .message-avatar img {
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
}

.msg .bubble, .message-bubble {
  min-width: 0 !important;
}

.msg.user .bubble, .message-row.user .message-bubble {
  text-align: right !important;
}

