  width: 31px !important;
  height: 31px !important;
  border-radius: 9px !important;
  overflow: hidden !important;
  background: #fff !important;
}

.auth-card .brand .logo img {
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
}

.auth-card .brand span:not(.logo) {
  font-family: var(--rd-display) !important;
  font-size: 18px !important;
  font-weight: 700 !important;
  color: #f7f8fb !important;
  letter-spacing: -.04em !important;
}

.auth-card .brand .grad-text {
  color: #8d93a2 !important;
  font-weight: 500 !important;
}

.auth-card h1 {
  font-family: var(--rd-display) !important;
  font-size: 28px !important;
  color: #f2f4f8 !important;
  margin-bottom: 6px !important;
  letter-spacing: -.04em !important;
}

.auth-card .sub {
  color: var(--rd-text-muted) !important;
  font-size: 13px !important;
  margin-bottom: 24px !important;
}

/* Form fields */
.field { margin-bottom: 16px !important; }

.field label {
  display: block !important;
  font-size: 11px !important;
  color: #72798a !important;
  margin-bottom: 6px !important;
  font-weight: 600 !important;
}

.input-wrap {
  display: flex !important;
  align-items: center !important;
  gap: 8px !important;
  border: 1px solid #303440 !important;
  background: #1c1f27 !important;
  border-radius: 8px !important;
  padding: 0 12px !important;
  transition: border-color .18s ease !important;
}

.input-wrap:focus-within {
  border-color: color-mix(in srgb, var(--accent) 58%, #303440) !important;
}

.input-wrap .lead-icon {
  color: #6f7584 !important;
  font-size: 13px !important;
}

.input-wrap input {
  flex: 1 !important;
  border: 0 !important;
  outline: 0 !important;
  background: none !important;
  color: #cfd3dd !important;
  font-size: 13px !important;
  font-family: var(--rd-font) !important;
  padding: 11px 0 !important;
}

.input-wrap input::placeholder { color: #6c7382 !important; }

.toggle-pw {
  border: 0 !important;
  background: none !important;
  color: #6f7584 !important;
  cursor: pointer !important;
  padding: 4px !important;
}

.pw-strength {
  margin-top: 6px !important;
  height: 3px !important;
  border-radius: 2px !important;
  background: #252934 !important;
  overflow: hidden !important;
}

.pw-strength span {
  display: block !important;
  height: 100% !important;
  width: 0 !important;
  border-radius: 2px !important;
  transition: width .3s ease, background .3s ease !important;
}

.auth-row {
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  margin-bottom: 20px !important;
  font-size: 12px !important;
}

.auth-row a { color: var(--accent-strong) !important; text-decoration: none !important; }
.auth-row label { display: flex; align-items: center; gap: 6px; color: #858c9b; font-size: 12px; cursor: pointer; }

.auth-or {
  text-align: center !important;
  color: var(--rd-text-dim) !important;
  font-size: 11px !important;
  margin: 18px 0 !important;
  position: relative !important;
}

.auth-or::before, .auth-or::after {
  content: '' !important;
  position: absolute !important;
  top: 50% !important;
  width: 40% !important;
  height: 1px !important;
  background: #252934 !important;
}

.auth-or::before { left: 0; }
.auth-or::after { right: 0; }

.auth-foot {
  text-align: center !important;
  color: var(--rd-text-muted) !important;
  font-size: 12px !important;
  margin-top: 20px !important;
}

.auth-foot a { color: var(--accent-strong) !important; text-decoration: none !important; }

.form-msg {
  display: none !important;
  padding: 10px 14px !important;
  border-radius: 8px !important;
  font-size: 12px !important;
  margin-bottom: 16px !important;
}

.form-msg.show { display: block !important; }
.form-msg.error { background: rgba(176,72,104,.12); border: 1px solid #5e3542; color: #db8ca6; }
.form-msg.success { background: rgba(95,196,165,.1); border: 1px solid #2d5e4f; color: #6dc6a4; }

/* Back home / theme toggle on auth pages */
.back-home {
  position: fixed !important;
  top: 20px !important;
  left: 20px !important;
  z-index: 100 !important;
  color: #8f95a5 !important;
  font-size: 12px !important;
  text-decoration: none !important;
  display: flex !important;
  align-items: center !important;
  gap: 6px !important;
  padding: 8px 12px !important;
  border-radius: 8px !important;
  border: 1px solid #292d38 !important;
  background: #171920 !important;
  transition: .18s ease !important;
}

.back-home:hover { color: #f0f2f7 !important; border-color: #303441 !important; }

.theme-toggle.floating {
  position: fixed !important;
  top: 20px !important;
  right: 20px !important;
  z-index: 100 !important;
}

/* ============ TOPIC PAGE ============ */
.topic-tab {
  display: flex !important;
  gap: 4px !important;
  border-bottom: 1px solid var(--rd-border) !important;
  margin-bottom: 20px !important;
  flex-wrap: wrap !important;
}

.topic-tab button {
  border: 0 !important;
  background: none !important;
  color: #8e95a5 !important;
  padding: 10px 14px !important;
  font-size: 12px !important;
  font-weight: 600 !important;
  cursor: pointer !important;
  border-bottom: 2px solid transparent !important;
  transition: .18s ease !important;
}

.topic-tab button:hover { color: #e3e6ed !important; }
.topic-tab button.active {
  color: #f4f6fb !important;
  border-bottom-color: var(--accent) !important;
}

.topic-panel { display: none !important; }
.topic-panel.active { display: block !important; }

/* Topic header */
#topicTitle {
  font-family: var(--rd-display) !important;
  font-size: 28px !important;
  color: #f2f4f8 !important;
  letter-spacing: -.04em !important;
}

/* ============ TOASTS ============ */
#toast-wrap {
  position: fixed !important;
  top: 20px !important;
  right: 20px !important;
  z-index: 9999 !important;
  display: flex !important;
  flex-direction: column !important;
  gap: 8px !important;
}

.toast {
  padding: 12px 16px !important;
  border-radius: 10px !important;
  font-size: 12px !important;
  border: 1px solid #303440 !important;
  background: #1b1e26 !important;
  color: #dfe2e9 !important;
  box-shadow: 0 8px 24px rgba(0,0,0,.3) !important;
  display: flex !important;
  align-items: center !important;
  gap: 8px !important;
}

.toast.error { border-color: #5e3542; color: #db8ca6; }
.toast.success { border-color: #2d5e4f; color: #6dc6a4; }

/* ============ MISC ============ */
.chip {
  display: inline-flex !important;
  align-items: center !important;
  gap: 5px !important;
  padding: 4px 10px !important;
  border-radius: 6px !important;
  font-size: 10px !important;
  font-weight: 600 !important;
  background: #1c1f27 !important;
  border: 1px solid #303440 !important;
  color: #8f95a5 !important;
  text-decoration: none !important;
}

.chip.clickable { cursor: pointer; }
.chip.clickable:hover { border-color: #454b5a; color: #cfd3dd; }

.skeleton {
  background: linear-gradient(90deg, #1c1f27 25%, #252934 50%, #1c1f27 75%) !important;
  background-size: 200% 100% !important;
  animation: rd-shimmer 1.5s infinite !important;
  border-radius: 6px !important;
  color: transparent !important;
}

@keyframes rd-shimmer {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}

#particles-js { display: none !important; }

/* ============ RESPONSIVE ============ */
@media (max-width: 980px) {
  .topbar { padding: 0 25px !important; }
  .settings-shell, .settings-layout { grid-template-columns: 1fr !important; gap: 15px !important; }
  .settings-nav { display: flex !important; overflow-x: auto !important; }
  .settings-nav button { white-space: nowrap !important; width: auto !important; }
  .sidebar { width: 222px !important; flex-basis: 222px !important; }
  .sidebar.collapsed { width: 76px !important; flex-basis: 76px !important; }
}

@media (max-width: 700px) {
  .sidebar {
    position: fixed !important;
    height: 100vh !important;
    left: -270px !important;
    width: 256px !important;
    flex-basis: 256px !important;
    transition: left .25s ease !important;
  }
  .sidebar.open { left: 0 !important; }
  .sidebar.collapsed { left: -270px !important; width: 256px !important; flex-basis: 256px !important; }
  .side-overlay.visible, .mobile-overlay.visible {
    display: block !important;
    position: fixed !important;
    z-index: 15 !important;
    inset: 0 !important;
    background: rgba(0,0,0,.55) !important;
  }
  .topbar { height: 64px !important; padding: 0 17px !important; }
  .topbar-actions .search-trigger { display: none !important; }
  .topbar h1 { font-size: 18px !important; }
  .dash-grid, .dash-grid-2 { grid-template-columns: 1fr !important; }
  .chat-layout { grid-template-columns: 1fr !important; }
  .chat-side { max-height: 260px; overflow: auto; }
  .auth-wrap { grid-template-columns: 1fr !important; }
  .auth-visual { display: none !important; }
  .auth-card { padding: 30px !important; }
  .set-field-grid { grid-template-columns: 1fr !important; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: .01ms !important;
    transition-duration: .01ms !important;
  }
}
